/**
 * Anointed
 * ----------
 * Samuel anoints the youngest son of Jesse, a shepherd boy of Bethlehem, while his elder brothers watch in surprise. Stage: a Bethlehem hillside at golden hour, sheep around, oil poured on a ruddy boy's head; a horn of oil, distant town rooftops; warm ochre light.
 *
 * Palette 0x2a3a1a → 0x0e1a08 · light: dawn · hero: horn
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./david-kit.js.
 */

import { THREE, createScene, cityGate, house, sheep, jar, horn, person, birds } from './david-kit.js';

const BG = 0x2a3a1a;
const GROUND = 0x060804;

export function build(group) {
    const W = createScene(group, { seed: 3637469813, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060804, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* city: gate, towers and houses on the far side */
    const city = W.grp(group, [19, 0, -58], { name: 'city', r: [0, -0.06, 0] });
    cityGate(W, city, 0, 0, 0, 1.15, { stone: 0x0f1b08, trim: 0x050603 });
    for (let i = 0; i < 5; i++) {
        house(W, city, -34 + i * 17 + W.rr(-4, 4), 0, W.rr(-14, 6), 0.85 + W.r() * 0.4, { mud: 0x0d1908 });
    }
    W.backdrop(city);

    /* flock: sheep grazing */
    sheep(W, group, 9.0, 0, -8.3, W.r() * 6, 0.89);
    sheep(W, group, 3.3, 0, -8.8, W.r() * 6, 1.09);
    sheep(W, group, 10.6, 0, -2.6, W.r() * 6, 0.86);
    sheep(W, group, -3.6, 0, -2.3, W.r() * 6, 0.94);
    sheep(W, group, 4.9, 0, -0.6, W.r() * 6, 1.18);
    sheep(W, group, -14.5, 0, -8.0, W.r() * 6, 0.99);
    sheep(W, group, -16.8, 0, -5.9, W.r() * 6, 1.04);

    jar(W, group, 7.1, 0, -5.7, );

    /* hero: the horn */
    horn(W, group, 0, 1.2, 0, 1.3, { color: 0x263417 });
    W.disc([0, 4, -10], 4, 0x374b22, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x8a6a44, head: 'wrap', wrap: 0x30431e, wrapTrim: 0x1d2912, beard: 'long', staff: 'planted', bend: 0.02, ry: -0.36, s: 1.08 });
    person(W, group, [4.5, 0, 6], { robe: 0x8a6a44, head: 'wrap', wrap: 0x30431e, wrapTrim: 0x1d2912, beard: 'long', staff: 'planted', bend: 0.02, ry: -0.10, s: 1.13 });

    /* birds: slow circles high above */
    birds(W, group, 5, 55, { y: 26 });

    return W.finish();
}

export default { build };
